#!/usr/bin/env bash
# GPT Image mockup：在 D 方向首屏真实截图上加 3D 食物装饰（4 个方向），另出 2 张竖版宣传片关键帧
set -u
cd "$(dirname "$0")"
G=~/.claude/skills/multimodal-extension/scripts/gpt_image.py
BASE=base-d-hero.png
KEEP="Edit this real website screenshot (a landing page for a fitness meal-planning tool). Keep the page structure, the cream background, all existing text exactly as written (Chinese and English, same fonts, same positions as much as possible), the black/red color scheme and the navigation. Do NOT add any extra text unless explicitly listed. No McDonald's logo, no golden arches, no brand packaging, wrappers, paper bags or cups. Clean, premium, Apple-style product page aesthetic; no neon, no glow, no dark background. Output an opaque image, 3:2 landscape."
edit() { python3 "$G" --input "$BASE" --background opaque --size 1536x1024 --quality high --output "$1.png" --prompt "$KEEP $2" > "$1.log" 2>&1; echo "done $1"; }
gen()  { python3 "$G" --background opaque --size 1024x1536 --quality high --output "$1.png" --prompt "$2" > "$1.log" 2>&1; echo "done $1"; }

edit m1-floating "Direction: photorealistic floating food. Add high-end photorealistic 3D-rendered fast food as decorative objects floating in the empty space around the giant headline: one double cheeseburger (glossy golden bun, two beef patties, two melting cheese slices, pickles, a little ketchup) seen from a 3/4 angle, plus two crispy chicken nuggets and one crispy fried chicken drumstick at smaller scales and different depths. Soft studio lighting, soft contact shadows on the page, very slight depth of field on the farthest piece. Objects must never cover any text." &
edit m2-barbell "Direction: the barbell mascot. Add one playful photorealistic 3D render as the hero centerpiece in the empty space beside the headline: a chrome gym barbell whose two weight plates are two thick double cheeseburgers (glossy buns, beef patties, melting cheese), lying at a slight angle as if just dropped after a set, with a soft shadow. Nearby, a small dumbbell whose two weights are chicken nuggets. Photoreal food, clean studio shadows, witty but premium. Objects must never cover any text." &
edit m3-exploded "Direction: exploded burger as the hero. Rearrange the hero so a large photorealistic 3D exploded view of a double cheeseburger sits on the right side: seven layers floating vertically with even gaps, from top: top bun, pickles with ketchup and onion, cheese slice, beef patty, cheese slice, beef patty, bottom bun. The two bun layers are rendered semi-transparent/ghosted to show they are set aside. Thin black leader lines go from the layers to small labels; the ONLY new text allowed is these labels, written exactly: 顶面包 留到明早 / 吉士 下单去掉 / 牛肉饼 91 大卡 / 底面包 留到明早, plus one large number 182 大卡. Keep the headline on the left." &
edit m4-claytoy "Direction: cute clay toys. Add cute stylized 3D clay-toy food characters (soft rounded forms, matte clay texture, tiny dot eyes and small smiles, no text on them) working out on the page: a double cheeseburger character doing a bicep curl with a tiny dumbbell, a chicken drumstick character doing a squat (leg day), a chicken nugget character doing a push-up on top of the TODAY · LEG DAY table line. Warm appetizing colors harmonised with the cream background and the red accent; soft shadows on the page. They must never cover any text." &
gen v1-explode "Vertical 9:16 keyframe for a cute, shareable short promo video. Warm cream background (#F2EDE4). Center: a photorealistic double cheeseburger mid-explosion, its layers floating apart vertically (top bun, pickles and ketchup, cheese, beef patty, cheese, beef patty, bottom bun); the two bun layers drift off to the side toward a small refrigerator icon area. Big bold black Chinese headline at the top, exactly: 只吃馅. Below the burger a huge red number, exactly: 182 大卡. Small text at the bottom, exactly: 面包留到明早当早餐. No other text, no logos, no golden arches, no packaging. Clean modern motion-graphics style, soft studio light." &
gen v2-legday "Vertical 9:16 keyframe for a cute, shareable short promo video. Warm cream background (#F2EDE4). A tiny miniature gym diorama: a photorealistic crispy fried chicken drumstick doing squats under a miniature barbell on a squat rack, two chicken nuggets resting on a mini bench, a small scoreboard. Big bold black Chinese text at the top, exactly: 今日训练：练腿. Red text below it, exactly: Never skip leg day. Small text at the bottom, exactly: 1 个一组，共 1 组. No other text, no logos, no golden arches, no packaging. Playful, premium, soft studio light, shallow depth of field." &
wait
